import{_ as l,a0 as u,w as p,s as i,ao as a,I as r,x as e,a1 as n,A as s}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const w=JSON.parse('{"title":"Kubernetes 即將支持機密計算 | LCTT x X-CMD","titleTemplate":false,"description":"Kubernetes 即將支持機密計算 | LCTT (202209) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Kubernetes 即將支持機密計算 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Kubernetes 即將支持機密計算 | LCTT (202209) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202209/20220923 Kubernetes To Soon Support Confidential Computing","title":"Kubernetes 即將支持機密計算","tag":"202209","desc":""},"relativePath":"202209/20220923 Kubernetes To Soon Support Confidential Computing.md","filePath":"[post].md"}'),d={name:"202209/20220923 Kubernetes To Soon Support Confidential Computing.md"};function m(b,t,C,f,T,S){const o=u("Link");return p(),i("div",null,[t[15]||(t[15]=a('<h1 id="kubernetes-即將支持機密計算" tabindex="-1">Kubernetes 即將支持機密計算 <a class="header-anchor" href="#kubernetes-即將支持機密計算" aria-label="Permalink to “Kubernetes 即將支持機密計算”">​</a></h1><p><img src="https://www.opensourceforu.com/wp-content/uploads/2022/09/kubernets-on-prem-diy-considerations-1.png" alt=""></p><blockquote><p>Constellation 是第一個始終加密的 kubernetes（K8S）。在這個 K8S 中，你的所有工作負載和控制平面都被完全屏蔽起來，你可以使用加密證書遠程確認這一點。</p></blockquote><p>Constellation Kubernetes 引擎使用 <ruby>秘密計算<rt>secret computing</rt></ruby> 和 <ruby>機密虛擬機<rt>confidential VM</rt></ruby>，將 Kubernetes 集羣與雲架構的其餘部分隔離開來。因此，無論是在靜態還是在內存中，數據總是被加密的，並創建了一個 <ruby>機密上下文<rt>confidential context</rt></ruby>。根據創建 Constellation 的公司 Edgeless Systems 的説法，由於它為在公共雲上運行的數據和工作流增加了安全性和保密性，因此機密計算是雲計算的未來。</p><p>Kubernetes 節點在使用 Constellation 的私有虛擬機中運行。根據 Edgeless Systems 的説法，機密虛擬機是安全飛地的演變，它將機密計算的三個原則——運行時加密、隔離和遠程證明——擴展到整個虛擬系統。機密虛擬機（TDX）使用底層硬件對私有計算的特殊支持，例如 AMD 安全加密虛擬化（AEM）、SEV-安全嵌套分頁（SEV-SNP）和英特爾信任域擴展。此外，ARM 去年還發布了名為 Realms 的新 V9 架構。此設計包括私有 VM 功能。</p><p>Constellation 嘗試在集羣級別提供證明或通過加密證書進行驗證，以及“始終在線”加密。 Constellation 中的機密 VMS 使用了 Fedora CoreOS，它構建在一個不可變的文件系統之上，是面向容器而設計的。Constellation 還利用 Sigstore 來保護 DevOps 信任鏈。</p><p>使用秘密計算時，性能可能會令人擔憂。是的，加密會影響性能，但 AMD 和微軟的聯合基準測試發現，這隻會導致 2% 到 8% 之間的微小性能損失。Edgeless Systems 聲稱 Constellation 將在繁重的工作負載下表現類似。</p><p>鑑於 Constellation 已通過 CNCF 認證，並且可與包括 GCP 和 Azure 在內的所有主要雲服務互操作，這應保證其與其他 Kubernetes 工作負載和工具的互操作性。</p><hr>',9)),r("p",null,[t[1]||(t[1]=e("via: ",-1)),n(o,{href:"https://www.opensourceforu.com/2022/09/kubernetes-to-soon-support-confidential-computing/"},{default:s(()=>[...t[0]||(t[0]=[e("https://www.opensourceforu.com/2022/09/kubernetes-to-soon-support-confidential-computing/",-1)])]),_:1})]),r("p",null,[t[6]||(t[6]=e("作者：",-1)),n(o,{href:"https://www.opensourceforu.com/author/laveesh-kocher/"},{default:s(()=>[...t[2]||(t[2]=[e("Laveesh Kocher",-1)])]),_:1}),t[7]||(t[7]=e(" 選題：",-1)),n(o,{href:"https://github.com/lkxed"},{default:s(()=>[...t[3]||(t[3]=[e("lkxed",-1)])]),_:1}),t[8]||(t[8]=e(" 譯者：",-1)),n(o,{href:"https://github.com/littlebirdnest"},{default:s(()=>[...t[4]||(t[4]=[e("littlebirdnest",-1)])]),_:1}),t[9]||(t[9]=e(" 校對：",-1)),n(o,{href:"https://github.com/wxy"},{default:s(()=>[...t[5]||(t[5]=[e("wxy",-1)])]),_:1})]),r("p",null,[t[12]||(t[12]=e("本文由 ",-1)),n(o,{href:"https://github.com/LCTT/TranslateProject"},{default:s(()=>[...t[10]||(t[10]=[e("LCTT",-1)])]),_:1}),t[13]||(t[13]=e(" 原創編譯，",-1)),n(o,{href:"https://linux.cn/"},{default:s(()=>[...t[11]||(t[11]=[e("Linux中國",-1)])]),_:1}),t[14]||(t[14]=e(" 榮譽推出",-1))])])}const x=l(d,[["render",m]]);export{w as __pageData,x as default};
